import math

def get_Min_Squares(n):
    if n is None or not isinstance(n, int) or n < 0:
        return None
    if n == 0:
        return 0
    max_square = int(math.isqrt(n))
    min_squares = [float('inf')] * (n + 1)
    min_squares[0] = 0
    for i in range(1, n + 1):
        for j in range(1, max_square + 1):
            square = j * j
            if square <= i:
                min_squares[i] = min(min_squares[i], min_squares[i - square] + 1)
    return min_squares[n]
